angle1_sections = [
    section("aops-angle-ledger", "Angle chasing is a reason ledger", "Mark only stated givens, then attach a reason to every new angle. The atomic moves are vertical angles equal, a linear pair sums to $180^\circ$, angles around a point sum to $360^\circ$, and triangle angles sum to $180^\circ$. A chase is valid because of this chain, not because the drawing resembles a familiar configuration.", "aops-angle-triangle.svg", "Triangle with two known angles and a marked exterior target.", "Each transferred or computed angle needs a named reason.", "Which note belongs in a valid reason ledger?", "$x=48^\circ+67^\circ$ by the exterior-angle theorem.", ["$x$ looks obtuse.", "$x$ is about $120^\circ$ from the drawing.", "$x$ equals the longest side."], "The note states both the relation and its justification."),
    section("aops-angle-intersections", "Intersections: vertical angles and linear pairs", "Opposite angles formed by two intersecting lines are vertical and equal. Adjacent angles whose noncommon sides form a line are a linear pair and sum to $180^\circ$. Decide whether the target is opposite or adjacent before choosing equality or supplementation.", "aops-angle-lines.svg", "Two parallel lines crossed by a transversal with marked interior angles.", "At each intersection, location determines whether angles are equal or supplementary.", "One angle at an intersection is $73^\circ$. What is an adjacent angle?", "$107^\circ$", ["$73^\circ$", "$17^\circ$", "$287^\circ$"], "Adjacent linear-pair angles sum to $180^\circ$."),
    section("aops-angle-triangle-sum", "Triangles and exterior angles", "Triangle interior angles total $180^\circ$. An exterior angle formed by extending one side equals the sum of the two remote interior angles; this follows by combining triangle sum with a linear pair. The remote angles are the two not adjacent to the exterior angle.", "aops-angle-triangle.svg", "Triangle ABC with remote interior angles 48 and 67 degrees and exterior angle x at C.", "The exterior target equals the two marked remote interior angles.", "For the shown values, what is $x$?", "$115^\circ$", ["$65^\circ$", "$67^\circ$", "$180^\circ$"], "$x=48^\circ+67^\circ=115^\circ$."),
    section("aops-angle-parallels", "Parallel lines transfer angles", "When parallel lines are cut by a transversal, corresponding and alternate interior angles are equal, while same-side interior angles are supplementary. These conclusions require an explicit parallel marking or a proved parallel relationship. Position names are safer than memorized letter shapes when a diagram is rotated.", "aops-angle-lines.svg", "Parallel lines l and m with a 62 degree angle alternate interior to x.", "The arrow marks supply the parallel hypothesis.", "In the marked diagram, what is $x$?", "$62^\circ$", ["$118^\circ$", "$28^\circ$", "Not enough information"], "Alternate interior angles between parallel lines are equal."),
    section("aops-angle-isosceles", "Equal sides transfer to equal angles", "In an isosceles triangle, equal sides face equal angles. The converse also holds: equal angles face equal sides. Mark which sides or angles are given equal before using the theorem. If a segment bisects the vertex angle of an isosceles triangle, congruent subtriangles often make it also a median and altitude.", "aops-angle-isosceles.svg", "Isosceles triangle ABC with AB equal AC and the 40 degree vertex angle bisected by AD.", "Equal sides and a bisected vertex angle create congruent halves.", "If the vertex angle is $40^\circ$, what is each base angle?", "$70^\circ$", ["$40^\circ$", "$80^\circ$", "$140^\circ$"], "The equal base angles share the remaining $140^\circ$."),
    section("aops-angle-direction", "Work forward and backward", "Forward work propagates known values. Backward work asks which equality or sum would determine the target. Meet in the middle: if the target is an exterior angle, seek its remote interiors; if it lies on a transversal, seek a transferable mate. Avoid computing every visible angle when only a short route is relevant.", "aops-angle-lines.svg", "A target angle x positioned across a transversal from a known 62 degree angle.", "Backward analysis identifies the exact transferable mate of x.", "What is the best backward question for target $x$ on a transversal?", "Which corresponding or alternate angle is linked to $x$?", ["How many angles can I label?", "Does $x$ look acute?", "Can I ignore the parallel marks?"], "The target's position determines the useful relation."),
    section("aops-angle-validation", "Validate the chase", "Check that triangle totals are $180^\circ$, angles around a point total $360^\circ$, and every angle measure lies between $0^\circ$ and $180^\circ$ unless a reflex angle is explicitly requested. Most importantly, audit every use of a converse and every parallel-line transfer for its missing hypothesis.", "aops-angle-triangle.svg", "Triangle and exterior angle configuration used to check an angle sum.", "A final sum check catches arithmetic and orientation errors.", "A chase gives triangle angles $48^\circ$, $67^\circ$, and $75^\circ$. What does the check reveal?", "The result is invalid because the sum is $190^\circ$.", ["The triangle is isosceles.", "The result is valid.", "The exterior angle is $75^\circ$."], "Interior angles of a triangle must sum to $180^\circ$.")]

angle1 = lesson("aops-angle-chasing-concept-lesson", "Angle Chasing I: Lines, Triangles, and Parallels", "aops-angle-chasing", "Angle chasing is controlled information propagation. Build a short chain of justified equalities and sums, and never treat visual appearance as a theorem.", ["Maintain a reason ledger for angle relations.", "Combine intersection, triangle, parallel-line, and isosceles facts.", "Validate a multi-step chase without relying on scale."], angle1_sections)

angle2_sections = [
    section("aops-angle2-central", "Central angles match their intercepted arcs", "A central angle has its vertex at the center, so its degree measure equals the measure of its intercepted arc. Identify the vertex before using this one-to-one relation; an angle whose vertex lies on the circle follows a different rule.", "aops-angle-circle.svg", "Central angle AOB of 104 degrees and inscribed angle ACB intercepting arc AB.", "The central angle and minor arc AB both measure 104 degrees.", "What is the measure of minor arc $AB$?", "$104^\circ$", ["$52^\circ$", "$208^\circ$", "$256^\circ$"], "A central angle has the same measure as its intercepted arc."),
    section("aops-angle2-inscribed", "Inscribed angles are half their arcs", "An inscribed angle has vertex on the circle and sides that are chords. Its measure is half the intercepted arc. Thus inscribed angles intercepting the same arc are equal. Be precise about which arc lies inside the angle; using the other arc changes the result.", "aops-angle-circle.svg", "Inscribed angle ACB marked x intercepting the same 104 degree arc as central angle AOB.", "The inscribed angle is half the central angle over the same arc.", "What is $x$ in the diagram?", "$52^\circ$", ["$104^\circ$", "$156^\circ$", "$208^\circ$"], "$x=104^\circ/2=52^\circ$."),
    section("aops-angle2-cyclic", "Opposite angles in a cyclic quadrilateral", "If all four vertices lie on one circle, opposite angles of the quadrilateral are supplementary. Each opposite pair intercepts arcs that together make the full circle, so their half-arc measures total $180^\circ$. The converse can prove concyclicity when a pair of opposite angles is supplementary.", "aops-angle-cyclic-tangent.svg", "Quadrilateral ABCD inscribed in a circle with all vertices visibly on the circumference.", "Concyclicity, not the shape's appearance, permits the supplementary conclusion.", "If angle $A=112^\circ$, what is opposite angle $C$?", "$68^\circ$", ["$112^\circ$", "$78^\circ$", "$248^\circ$"], "Opposite angles of a cyclic quadrilateral sum to $180^\circ$."),
    section("aops-angle2-tangent-chord", "A tangent-chord angle matches an inscribed angle", "The angle between a tangent at $A$ and chord $AB$ equals any inscribed angle intercepting chord $AB$ on the opposite arc. A reliable proof draws radius $OA$, uses $OA$ perpendicular to the tangent, then relates the isosceles central triangle to the relevant arc. Do not use this theorem when the line is a secant.", "aops-angle-cyclic-tangent.svg", "Tangent at A, chord AB, and inscribed angle ADB of 38 degrees intercepting chord AB.", "Both marked angles are tied to the same chord AB.", "What is tangent-chord angle $y$?", "$38^\circ$", ["$52^\circ$", "$76^\circ$", "$142^\circ$"], "The tangent-chord theorem equates it to inscribed angle $ADB$."),
    section("aops-angle2-radius", "Draw a radius to unlock circle angles", "When a tangent or chord is present, a radius can expose a right angle or an isosceles triangle. Draw to a tangency point for perpendicularity; draw to chord endpoints for equal sides. State the intended result before adding the line, because an arbitrary radius may not connect to the target.", "aops-angle-cyclic-tangent.svg", "Circle configuration containing a tangent at A and chord AB.", "Radius OA would create a justified right angle with the tangent.", "Which construction directly uses the tangent at $A$?", "Draw radius $OA$.", ["Draw any diameter not through $A$.", "Assume $AB$ passes through the center.", "Reflect the tangent without justification."], "The contact radius is perpendicular to the tangent."),
    section("aops-angle2-mixed", "Combine line and circle moves", "A mixed chase often follows this order: use parallel or isosceles facts to obtain one inscribed angle, convert it to an arc, and transfer that arc to another inscribed or tangent-chord angle. Record the intermediate arc explicitly so the factor of two is not lost.", "aops-angle-circle.svg", "Central and inscribed angles sharing the marked arc AB.", "Writing the arc measure makes the central-versus-inscribed factor visible.", "An inscribed angle intercepting arc $AB$ is $37^\circ$. What central angle intercepts the same arc?", "$74^\circ$", ["$18.5^\circ$", "$37^\circ$", "$143^\circ$"], "The arc and central angle are twice the inscribed angle."),
    section("aops-angle2-proof", "Converse checks and proof closure", "Circle angle theorems are conditional. Confirm vertex location, intercepted arc, tangency, or concyclicity before applying one. To close a proof, restate the target relation and cite the final theorem. Numerical agreement alone does not prove that an unmarked quadrilateral is cyclic.", "aops-angle-cyclic-tangent.svg", "Marked cyclic quadrilateral and tangent configuration.", "The circle and contact markings carry hypotheses that the proof must name.", "Which condition can prove four points concyclic?", "A pair of opposite quadrilateral angles sums to $180^\circ$.", ["Two adjacent angles are unequal.", "One diagonal looks like a diameter.", "Two sides appear parallel."], "The converse of the cyclic-quadrilateral theorem establishes concyclicity.")]

angle2 = lesson("aops-angle-chasing-circle-mixed-concept-lesson", "Angle Chasing II: Circle and Mixed Proof Chases", "aops-angle-chasing", "Circle configurations add arc conversion, cyclic quadrilaterals, tangent-chord angles, and purposeful auxiliary radii to the reason ledger.", ["Relate central angles, arcs, and inscribed angles.", "Use cyclic and tangent-chord conditions in both calculation and proof.", "Plan mixed line-and-circle chases."], angle2_sections)


def worked(aid, title, topic, skills, problems):
    rows = []
    for pi, (ptitle, problem, image, alt, steps) in enumerate(problems, 1):
        outsteps = []
        for si, (stitle, instruction, prompt, correct, wrong, expl) in enumerate(steps, 1):
            row = {"id": f"{aid}-p{pi}-s{si}", "title": stitle, "instruction": instruction,
                   "type": "multipleChoice", "prompt": prompt,
                   "choices": [{"id": x, "text": t} for x, t in zip("abcd", [correct]+wrong)],
                   "answer": {"choiceId": "a"}, "explanation": expl}
            if si == 1:
                row["media"] = [{"type": "image", "src": f"/assessments/aops/{image}", "alt": alt,
                                  "caption": "Use only the labels and markings stated in the problem."}]
            outsteps.append(row)
        rows.append({"id": f"{aid}-problem-{pi}", "title": ptitle, "problem": problem, "steps": outsteps})
    return {"schemaVersion": 1, "id": aid, "title": title, "assessmentType": "workedExample",
            "categoryId": "art-of-problem-solving", "topicId": topic, "modeDefault": "practice",
            "randomizeQuestions": False, "navigation": {"learningGoal": "learn", "activityType": "guidedWorkedExample", "tags": ["art-of-problem-solving", topic, "aops-volume-1", "geometry", "worked-example"]},
            "skills": skills, "workedExamples": rows}


def s(title, instruction, prompt, correct, b, c, d, explanation): return (title, instruction, prompt, correct, [b,c,d], explanation)

