def glossary(aid, title, topic, entries):
    made=[]
    for term_id, term, definition, notation, example, aliases in entries:
        made.append({"id": term_id, "term": term, "definition": definition, "notation": notation,
                     "examples": [example], "aliases": aliases, "media": [], "tags": [term_id, topic],
                     "drills": [{"id": f"{term_id}-definition-drill", "type": "typed",
                                 "prompt": f"Name the term: {definition}",
                                 "answer": {"expected": term, "aliases": aliases},
                                 "explanation": f"The defining feature identifies {term}.", "tags": [term_id, topic]}]})
    return {"schemaVersion":1,"id":aid,"title":title,"assessmentType":"glossary","categoryId":"art-of-problem-solving","topicId":topic,"modeDefault":"practice","randomizeQuestions":True,"navigation":{"learningGoal":"learn","activityType":"glossary","tags":["art-of-problem-solving",topic,"aops-volume-1","geometry","terminology"]},"skills":["Recognize and use the topic's geometric vocabulary precisely."],"glossary":{"introduction":"Definitions include the condition that permits each theorem; use the drills to distinguish easily confused objects.","sections":[{"id":f"{topic}-terms","title":"Terms, conditions, and recognition cues","required":True,"content":"Name an object from its defining incidence or measurement facts, not from how a drawing looks.","entries":made}]}}

